using System; using System.Reflection; class I { static int Main(){var a=Assembly.LoadFrom(@"F:\vam1.22.0.12\VaM_Data\Managed\Assembly-CSharp.dll"); foreach(var tn in new[]{"SuperController","OVRInput"}){var t=a.GetType(tn); Console.WriteLine("TYPE="+t); foreach(var f in t.GetFields(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static)){var n=f.Name.ToLowerInvariant(); if(n.Contains("navigation")||n.Contains("camera")||n.Contains("free")||n.Contains("move")||n.Contains("rotate"))Console.WriteLine("FIELD "+f.FieldType+" "+f.Name+" public="+f.IsPublic);} foreach(var p in t.GetProperties(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static)){var n=p.Name.ToLowerInvariant(); if(n.Contains("navigation")||n.Contains("camera")||n.Contains("free")||n.Contains("move")||n.Contains("rotate"))Console.WriteLine("PROP "+p.PropertyType+" "+p.Name);} } return 0; }}
